import java.util.Set;

import java.util.HashSet;

class EthnicityClassifier {
    private static Set<String> ethnicities = new HashSet<>();

    public static boolean classify(String name) {
        // Iterate through all registered ethnicities and check if name contains the ethnic name
        for (String ethnicity : ethnicities) {
            if (name.contains(ethnicity)) {
                return true;
            }
        }

        return false;
    }

    public static void registerEthnicity(String name) {
        // Add new ethnicities to the classifier's set
        ethnicities.add(name);
    }

    public static void main(String[] args) {
        // Register the ethnic group before classification
        registerEthnicity("Scottish");

        // Test name for classification
        String testName = "Mr. Wallace";
        // Use classify method to determine if name belongs to registered ethnicity
        boolean isScottish = classify(testName);
        System.out.println("Is " + testName + " Scottish? " + isScottish);
    }
}

