import os

# Helper function to check if a file exists at the given path (keep but refactor for security)
def check_file_exists(filename):
    return os.path.isfile(filename)

# New function to verify that files added to the database have the expected permissions
def check_file_permissions(filename):
    # Confirm the file actually exists before testing further
    if not os.path.isfile(filename):
        return False

    # Check that the file has read permissions for all users
    if not os.access(filename, os.R_OK):
        return False

    # Verify file can be executed by other users for maximum security coverage
    if not os.access(filename, os.X_OK):
        return False

    return True

