import os
import glob

def delete_all_files(folder):
    # Use glob with wildcard to match all files and directories recursively
    for file in glob.glob(os.path.join(folder, '**'), recursive=True):
        # os.remove() deletes files, os.rmdir() removes directories
        if os.path.isfile(file):
            os.remove(file)
        else:
            os.rmdir(file)

