import os

def clear_log_dir(log_dir_path):
    # Iterate through root dir to access all files for deletion
    for root, subdirs, files in os.walk(log_dir_path):
        os.chmod(root, 0o777)  # Set full permissions on directory to prevent write errors
        for filename in files:
            filepath = os.path.join(root, filename)
            os.chmod(filepath, 0o777)  # Set file permissions for each log to ensure deletion
            os.unlink(filepath)  # Remove the file from the filesystem

if __name__ == "__main__":
    # Call function with path to log directory
    clear_log_dir('/var/log/my_app/logs')

